# Add to SimEventType
class SimEventType(Enum):
    MOVED     = "moved"
    BLOCKED   = "blocked"
    BUMPED    = "bumped"      # ← new
    ROTATED   = "rotated"
    HARVESTED = "harvested"
    GAVE      = "gave"
    ATE       = "ate"
    STARVED   = "starved"
    DIED      = "died"
    ATTACKED  = "attacked"
    COUNTERED = "countered"


_FREE = {Instruction.ROT_L, Instruction.ROT_R}
_COSTS_ONE = {Instruction.PAUSE, Instruction.DEFEND,
              Instruction.HARVEST, Instruction.GIVE, Instruction.SETTLE}

